import type { paths } from './schema'

/** Types derived from the OpenAPI document generated by openapi-typescript. */
export type MeHomeResponse = paths['/api/v1/me/home']['get']['responses'][200]['content']['application/json']
export type GeneratedApiPaths = paths
export type ContributionEndpointPath = Extract<
  keyof paths,
  `/api/v1/stokvels/${string}/contributions`
>
export type ContributionEndpoint = paths[ContributionEndpointPath]

/** UI view models. The later API adapter maps contract responses into these props. */
export type StokvelRole = 'Treasurer' | 'Member'
export type CycleStatus = 'Open' | 'Closed' | 'PaidOut'
export type ContributionStatus = 'Pending' | 'Paid' | 'Confirmed'

export interface StokvelCardProps {
  id: string
  name: string
  role: StokvelRole
  cycleNumber: number | null
  cycleName: string | null
  cycleStatus: CycleStatus | null
  dueDate: string | null
  paidThisCycleCents: number | null
  stillOwedCents: number | null
  nextPayoutAt: string | null
}

export interface ContributionCardProps {
  id: string
  stokvelName: string
  amountCents: number
  status: ContributionStatus
  paidAt: string | null
  cycleNumber: number
  cycleName: string
  contributorName?: string
}
